"""Subtitle font catalog (frontend/public/fonts/fonts.json, generated by
scripts/fetch_fonts.py) and text measurement with the very same font files."""

from __future__ import annotations

import json
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

from PIL import ImageFont, features

from ..config import get_settings


@dataclass(frozen=True)
class FontFace:
    family_id: str
    weight: int
    path: Path
    internal_name: str
    units_per_em: int
    ascent: int
    descent: int
    ass_ratio: float

    def ass_size(self, css_px: float) -> float:
        """libass font size that renders glyphs with em = ``css_px``."""
        return css_px * self.ass_ratio

    def line_height(self, css_px: float) -> float:
        return css_px * (self.ascent + self.descent) / self.units_per_em


@lru_cache
def catalog(fonts_dir: Path | None = None) -> dict[str, list[FontFace]]:
    root = fonts_dir or get_settings().fonts_dir
    data = json.loads((root / "fonts.json").read_text())
    out: dict[str, list[FontFace]] = {}
    for fam in data:
        out[fam["id"]] = [
            FontFace(
                family_id=fam["id"],
                weight=w["weight"],
                path=root / w["file"],
                internal_name=w["internalName"],
                units_per_em=w["unitsPerEm"],
                ascent=w["ascent"],
                descent=w["descent"],
                ass_ratio=w["assRatio"],
            )
            for w in fam["weights"]
        ]
    return out


def resolve_face(family_id: str, weight: int, fonts_dir: Path | None = None) -> FontFace:
    """Closest available weight of the family (falls back to Montserrat)."""
    cat = catalog(fonts_dir)
    faces = cat.get(family_id) or cat.get("montserrat") or next(iter(cat.values()))
    return min(faces, key=lambda f: (abs(f.weight - weight), -f.weight))


_LAYOUT = ImageFont.Layout.RAQM if features.check("raqm") else ImageFont.Layout.BASIC


@lru_cache(maxsize=256)
def _pil_font(path: str, size: float) -> ImageFont.FreeTypeFont:
    return ImageFont.truetype(path, size=size, layout_engine=_LAYOUT)


def text_width(face: FontFace, text: str, css_px: float) -> float:
    """Advance width of ``text`` in px at em size ``css_px`` (measured at 10x for precision)."""
    if not text:
        return 0.0
    font = _pil_font(str(face.path), round(css_px * 10, 1))
    return font.getlength(text) / 10.0
